function PVPArenaPlayerQuizDialog:RefreshUI(oneMatchChartData, preSeasonId)
    local leftInfo      = oneMatchChartData.leftInfo
    local leftPlayerId  = oneMatchChartData.leftPlayerId
    self:RefreshQuizInfoNode(self.PanelL, leftInfo, leftPlayerId, preSeasonId)

    local rightInfo     = oneMatchChartData.rightInfo
