    self:RefreshQuizInfoNode(self.PanelR, rightInfo, rightPlayerId, preSeasonId)

end

function PVPArenaPlayerQuizDialog:RefreshQuizInfoNode(gameObject, info, playerId, preSeasonId)
    ---@type PVPArenaPlayerQuizInfoNode
    local env = CfUtils.GetLuaScr(gameObject, PVPArenaPlayerQuizInfoNodePath)
    if isNull(env) then return end
    env:SetSeasonId(preSeasonId)
    env:RefreshUI(info, playerId)
end

